export function buildWorldMarketSchedule(startISO = null) {
  return buildScheduleFor(WORLD_MARKET_MODULES, startISO, WORLD_MARKET_META.cadenceDays);
}

export function worldMarketProgressSummary(progress = {}) {
  return progressSummaryFor(WORLD_MARKET_MODULES, progress);
}

export function exportWorldMarketCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: WORLD_MARKET_META,
    modules: buildWorldMarketSchedule(startISO),
    sessionFlow: WORLD_MARKET_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function worldMarketRefs() {
  const seen = new Set();
  for (const m of WORLD_MARKET_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((WORLD_MARKET_META.wordFirst && WORLD_MARKET_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

